"""Regenerate app/badgePlaceholders.js from the badge artwork in public/.

The hero badges show these tiny images, pixelated, while the full artwork
loads. Run after replacing any card image:

    python3 scripts/make-badge-placeholders.py
"""
import base64
import io
from pathlib import Path

from PIL import Image

ROOT = Path(__file__).resolve().parent.parent
FACES = {
    "front": "card-front.png",
    "back": "card-back.png",
    "secondFront": "card-front-2.png",
    "secondBack": "card-back-2.png",
}
SIZE = (24, 34)

lines = [
    "// Generated by scripts/make-badge-placeholders.py. Do not edit by hand.",
    "// Tiny versions of the badge artwork, shown pixelated until the full images load.",
    "export const badgePlaceholders = {",
]
for key, name in FACES.items():
    image = Image.open(ROOT / "public" / name).convert("RGB").resize(SIZE, Image.LANCZOS)
    buffer = io.BytesIO()
    image.save(buffer, format="PNG", optimize=True)
    data = base64.b64encode(buffer.getvalue()).decode()
    lines.append(f'  {key}: "data:image/png;base64,{data}",')
lines.append("};")
(ROOT / "app" / "badgePlaceholders.js").write_text("\n".join(lines) + "\n")
print("wrote app/badgePlaceholders.js")
